import React, { useEffect, useState } from "react";
import "./Gallery.css";

export default function Gallery() {
  const [items, setItems] = useState([]);
  useEffect(() => {
    setItems([
      {id:1,title:"Autonomous Robot Arm",img:"https://via.placeholder.com/300x200?text=Robot+Arm"},
      {id:2,title:"AI Rover",img:"https://via.placeholder.com/300x200?text=AI+Rover"},
      {id:3,title:"Drone Bot",img:"https://via.placeholder.com/300x200?text=Drone+Bot"}
    ]);
  },[]);
  return (
    <section className="gallery">
      <h2>Featured Robotics Projects</h2>
      <div className="gallery-grid">
        {items.map(item=>(
          <div key={item.id} className="gallery-item">
            <img src={item.img} alt={item.title}/>
            <p>{item.title}</p>
          </div>
        ))}
      </div>
    </section>
  );
}
