import React from "react";
import "./Hero.css";


export default function Hero() {
  return (
    <section className="hero">
      <div className="hero-left">
        <h1>BotVerse</h1>
        <p className="lead">
          The all-in-one robotics hub — hardware, software, tutorials, and a community that helps you build.
        </p>
        <div className="hero-cta">
          <a className="btn" href="/builder">Start your robotics site</a>
          <a className="btn ghost" href="/videos">Watch robotics videos</a>
        </div>
      </div>

      <div className="hero-right">
        <div className="robot-orbit">
          {/* Simple robot SVG; rotating parts via CSS */}
          <svg viewBox="0 0 200 200" className="robot-svg">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stopColor="#00d4ff" />
                <stop offset="1" stopColor="#3b82f6" />
              </linearGradient>
            </defs>

            <g transform="translate(100,100)">
              <g className="orbit">
                <circle r="70" fill="none" stroke="url(#g1)" strokeWidth="2" />
              </g>

              <g className="robot">
                <rect x="-30" y="-20" rx="6" ry="6" width="60" height="40" fill="#0b1220" stroke="#00d4ff" strokeWidth="2"/>
                <circle cx="-12" cy="-8" r="4" fill="#fff"/>
                <circle cx="12" cy="-8" r="4" fill="#fff"/>
                <rect x="-18" y="6" width="36" height="6" rx="3" fill="#00d4ff"/>
                <g className="antenna" transform="translate(0,-30)">
                  <rect x="-2" y="-10" width="4" height="12" rx="2" fill="#3b82f6"/>
                  <circle r="3" fill="#00d4ff" />
                </g>
              </g>

              <g className="rotor">
                <rect x="-2" y="-70" width="4" height="12" fill="#3b82f6" rx="2" />
                <circle cx="0" cy="-80" r="6" fill="#00d4ff" />
              </g>
            </g>
          </svg>
        </div>
      </div>
    </section>
  );
}
